sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
let recordInfo = event.context.item.value;
    let sysId = recordInfo.sysId;
    let table = '';
    if(recordInfo.type == "Problem")
        table = 'problem';
    else if(recordInfo.type == 'Change request' || recordInfo.type == 'Caused by change')
        table = 'change_request';

    let customPayload = {
        "route": 'record',
        "targetRoute": null,
        "fields": {
            table: table,
            sysId: sysId
        },
        "params": {
            selectedTabIndex: 0
        },
        "redirect": true,
        "passiveNavigation": null,
        "title": null,
        "multiInstField": null,
        "external": null
    };
    api.emit('NAV_ITEM_SELECTED', customPayload);
}
